      "en": "In this perspective, Paul, incarnation cannot be reduced to a biological fact: **gabriel marcel:** very early on, paul, i experienced a suffocating dissatisfaction before the abstract idealism of léon brunschvicg and the neo-kantians. existence presented itself to me not as a general concept to be subsumed under categories, but as an insurmountable, incarnate, raw insertion into the fabric of the real."
