      "secEn": "First Dialogue: From Existence to Incarnation",
      "pNum": 111,
      "fr": "Ainsi se prépare l'accès aux démarches plus hautes de la réflexion seconde : **paul ricœur :** gabriel marcel, lorsque l'on relit vos premières méditations de 1914, on est frappé par votre refus immédiat du rationalisme académique. comment est née cette rupture initiale avec l'idéalisme ?",
