      "en": "In *A Man of God*, Pastor Lemoyne undergoes the mortal temptation of transforming his drama into a psychological problem: **gabriel marcel:** primary reflection dissects, analyzes, objectifies, and isolates elements to dominate them—it is the indispensable tool of positive sciences. but secondary reflection is recuperative: it gathers what analysis shattered, reintegrating the knowing subject within the living presence of being."
