      "fr": "Le recueillement n'est point évasion hors du réel, mais rassemblement intime de toutes nos énergies d'accueil : **gabriel marcel :** le témoignage est l'acte par lequel j'engage ma liberté pour attester d'une réalité qui me dépasse et dont je suis le dépositaire sacré.",
