      "pNum": 281,
      "fr": "Dans *Le Dard*, la fidélité de Werner Schnee s'affirme comme un défi héroïque lancé à la haine ambiante : **paul ricœur :** venons-en, gabriel marcel, à votre célèbre distinction entre *problème* et *mystère*. pourquoi cette frontière est-elle la clé de voûte de toute votre philosophie ?",
