      "en": "This dialectic of fidelity and mystery leads us directly to the threshold of hope: **gabriel marcel:** the unavailable being is encumbered with himself, entirely confined within his possessions and petty preoccupations. the available being, on the contrary, is permeable to the call of the other, ready to welcome the unforeseen gift of grace."
