      "secEn": "Second Dialogue: Mystery, Secondary Reflection, and Fidelity",
      "pNum": 398,
      "fr": "Cette dialectique de la fidélité et du mystère nous conduit tout droit au seuil de l'espérance : **gabriel marcel :** l'être indisponible est encombré de soi-même, tout entier confiné dans ses possessions et ses préoccupations mesquines. l'être disponible, au contraire, est perméable à l'appel d'autrui, prêt à accueillir l'imprévu de la grâce.",
