      "fr": "La protestation contre la mort prend toute sa force dans le recueillement de la prière : **paul ricœur :** c'est ce que vous résumez dans cette formule admirable : « j'espère en toi pour nous » ?",
      "en": "The protest against death assumes all its strength in the recollection of prayer: **paul ricœur:** is this what you summarize in that admirable formula: 'i hope in thee for us'?"
