      "en": "It is upon this perfect chord of hope and faith that we seal our conversations: **gabriel marcel:** the philosopher is a watchman in the heart of the night. his mission is not to erect dogmatic fortresses, but to hold ajar the door to the invisible and rekindle fraternal hope among human beings."
